const { withAppBuildGradle } = require('expo/config-plugins');

const PHONE_APPLICATION_ID = 'io.github.gregorgregor25.t1arc';
const DEFAULT_CONFIG_MARKER =
  '        // @generated by with-t1arc-application-id';
const DEBUG_MARKER =
  '            // @generated T1 Arc debug application identity';
const RELEASE_MARKER =
  '            // @generated T1 Arc release application identity';

function insertBuildTypePolicy(contents, buildType, marker, policy) {
  if (contents.includes(marker)) return contents;

  const buildTypesStart = contents.indexOf('\n    buildTypes {');
  const header = `        ${buildType} {`;
  const blockStart = contents.indexOf(header, buildTypesStart);
  if (buildTypesStart < 0 || blockStart < 0) {
    throw new Error(
      `T1 Arc could not locate the Android ${buildType} build type.`,
    );
  }

  const insertionPoint = blockStart + header.length;
  return `${contents.slice(0, insertionPoint)}\n${policy}${contents.slice(
    insertionPoint,
  )}`;
}

function injectT1ArcApplicationId(contents) {
  let next = contents;

  if (!next.includes(DEFAULT_CONFIG_MARKER)) {
    const applicationIdLines = [
      ...next.matchAll(/^([ \t]*)applicationId\s+['"]([^'"]+)['"]\s*$/gm),
    ];
    if (applicationIdLines.length !== 1) {
      throw new Error(
        'T1 Arc expected exactly one generated Android applicationId line.',
      );
    }
    const [line, indentation, applicationId] = applicationIdLines[0];
    if (applicationId !== PHONE_APPLICATION_ID) {
      throw new Error(
        `T1 Arc generated an unexpected phone application ID: ${applicationId}`,
      );
    }
    next = next.replace(
      line,
      `${DEFAULT_CONFIG_MARKER}\n${indentation}applicationId t1ArcPhoneApplicationId`,
    );
  }

  next = insertBuildTypePolicy(
    next,
    'debug',
    DEBUG_MARKER,
    `${DEBUG_MARKER}
            applicationIdSuffix t1ArcDebugApplicationIdSuffix
            resValue "string", "t1arc_application_id", t1ArcVariantApplicationId(t1ArcPhoneApplicationId, "debug")`,
  );
  next = insertBuildTypePolicy(
    next,
    'release',
    RELEASE_MARKER,
    `${RELEASE_MARKER}
            if (t1ArcReleaseApplicationIdSuffix != null) {
                applicationIdSuffix t1ArcReleaseApplicationIdSuffix
            }
            resValue "string", "t1arc_application_id", t1ArcVariantApplicationId(t1ArcPhoneApplicationId, "release")`,
  );

  return next;
}

function withT1ArcApplicationId(config) {
  return withAppBuildGradle(config, (androidConfig) => {
    if (androidConfig.modResults.language !== 'groovy') {
      throw new Error(
        'T1 Arc application identity currently expects a Groovy app build file.',
      );
    }
    androidConfig.modResults.contents = injectT1ArcApplicationId(
      androidConfig.modResults.contents,
    );
    return androidConfig;
  });
}

module.exports = withT1ArcApplicationId;
module.exports.injectT1ArcApplicationId = injectT1ArcApplicationId;
